 static int tests=0;
 static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);tests++;System.out.println("PASS "+name);}
 static JSONObject profile(String kind){return J.obj("name","SYNTHETIC","protocol",kind,"baseUrl","https://api.synthetic.example/v1","maxTokens",4096,"contextChars",100000,"timeout",30,"extra","{}","stream",true);}
 static void fails(Runnable f,String name){try{f.run();}catch(IllegalArgumentException e){check(true,name);return;}throw new AssertionError(name);}
 public static void main(String[] args)throws Exception{
  for(String kind:ApiProtocol.TYPES){JSONObject p=ApiProtocol.validate(profile(kind));JSONArray history=new JSONArray().put(J.obj("role","user","content","合成问题"));JSONObject payload=ApiProtocol.payload(p,"synthetic-model","合成项目说明",history);check(!payload.toString().contains("SYNTHETIC_KEY"),kind+" key absent from body");check(ApiProtocol.headers(p,"SYNTHETIC_KEY").size()>=3,kind+" protocol authentication");check(ApiProtocol.endpoint(p,"synthetic-model",false).startsWith("https://"),kind+" HTTPS endpoint");}
  check(ApiProtocol.normalizeBase("https://example.org/v1/chat/completions/").equals("https://example.org/v1"),"full chat endpoint normalized once");
  fails(()->ApiProtocol.normalizeBase("http://example.org/v1"),"HTTP rejected");fails(()->ApiProtocol.normalizeBase("https://user:pass@example.org/v1"),"URL embedded credentials rejected");fails(()->ApiProtocol.normalizeBase("https://example.org/v1?key=secret"),"URL query key rejected");fails(()->ApiProtocol.validate(J.obj("name","test","protocol","chat","baseUrl","https://example.org","extra","{\"n\":2}")),"multiple generation override rejected");
  JSONArray messages=new JSONArray().put(J.obj("role","user","body","合成问题","state","done")).put(J.obj("role","assistant","body","合成未完成稿","state","interrupted")).put(J.obj("role","assistant","body","合成完成稿","state","done"));JSONArray context=Conversation.history(messages);check(context.length()==3&&context.toString().contains("未完成"),"visible partial preserved for explicit continuation without automatic replay");
  String instructions=Conversation.instructions(J.obj("instructions","合成项目一"),new JSONArray().put(J.obj("name","合成参考.txt","body","合成参考内容")));check(instructions.contains("合成项目一")&&instructions.contains("合成参考内容"),"project instructions and references included without another call");
  JSONObject p=profile("chat");p.put("contextChars",3);boolean limited=false;try{ApiProtocol.payload(p,"m",instructions,context);}catch(IllegalArgumentException e){limited=true;}check(limited,"long context rejected without silent history truncation");
  JSONObject secret=J.obj("keyCipher","SYNTHETIC_ENCRYPTED","nested",J.obj("apiKey","SYNTHETIC_KEY","value","safe"));check(!J.noSecrets(secret).toString().contains("SYNTHETIC"),"export recursively removes credentials");
  ApiProtocol.Output chat=new ApiProtocol.Output();chat.event("chat","","{\"choices\":[{\"delta\":{\"content\":\"合成回答\"},\"finish_reason\":null}]}");chat.event("chat","","{\"choices\":[{\"delta\":{},\"finish_reason\":\"stop\"}],\"usage\":{\"completion_tokens\":4}}");check(chat.complete()&&chat.text.toString().equals("合成回答"),"chat SSE accumulated");check(chat.usage.optInt("completion_tokens")==4,"chat SSE usage recorded");
  ApiProtocol.Output r=new ApiProtocol.Output();r.event("responses","","{\"type\":\"response.output_text.delta\",\"delta\":\"合成R\"}");r.event("responses","","{\"type\":\"response.completed\",\"response\":{\"id\":\"synthetic\",\"usage\":{\"output_tokens\":2}}}");check(r.complete()&&r.text.toString().equals("合成R"),"Responses SSE accumulated");
  ApiProtocol.Output c=new ApiProtocol.Output();c.event("claude","","{\"type\":\"message_start\",\"message\":{\"usage\":{\"input_tokens\":12}}}");c.event("claude","","{\"type\":\"content_block_delta\",\"delta\":{\"type\":\"text_delta\",\"text\":\"合成C\"}}");c.event("claude","","{\"type\":\"message_delta\",\"delta\":{\"stop_reason\":\"end_turn\"},\"usage\":{\"output_tokens\":3}}");c.event("claude","","{\"type\":\"message_stop\"}");check(c.complete()&&c.usage.optInt("input_tokens")==12&&c.usage.optInt("output_tokens")==3,"Claude native stream and cumulative usage");
  ApiProtocol.Output g=new ApiProtocol.Output();g.event("gemini","","{\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"不展示的合成思考\",\"thought\":true},{\"text\":\"合成G\"}]},\"finishReason\":\"STOP\"}],\"usageMetadata\":{\"candidatesTokenCount\":3}}");check(g.complete()&&g.text.toString().equals("合成G"),"Gemini native stream extracts public text");
  ApiProtocol.Output cut=new ApiProtocol.Output();cut.event("chat","","{\"choices\":[{\"delta\":{\"content\":\"合成部分\"},\"finish_reason\":\"length\"}]}");check(!cut.complete()&&cut.text.length()>0,"token limit is incomplete, preserves answer");
  ArrayList<String> frames=new ArrayList<>();ApiClient.readSse(new StringReader("\uFEFF: ping\r\nevent: custom\r\ndata: line1\r\ndata: line2\r\n\r\ndata: final"),(event,data)->frames.add(event+"="+data));check(frames.equals(Arrays.asList("custom=line1\nline2","=final")),"SSE BOM CRLF multiline and final event");
  ApiProtocol.Output nonstream=new ApiProtocol.Output();nonstream.full("responses",new JSONObject("{\"error\":null,\"status\":\"completed\",\"output\":[{\"type\":\"message\",\"content\":[{\"type\":\"output_text\",\"text\":\"合成完整回复\"}]}]}"));check(nonstream.complete()&&nonstream.text.toString().equals("合成完整回复"),"Responses non-stream with null error is valid");
  ApiProtocol.Output nonstreamClaude=new ApiProtocol.Output();nonstreamClaude.full("claude",new JSONObject("{\"content\":[{\"type\":\"text\",\"text\":\"合成C完整\"}],\"stop_reason\":\"end_turn\"}"));check(nonstreamClaude.complete(),"Claude non-stream parsed");
  ApiProtocol.Output nonstreamGemini=new ApiProtocol.Output();nonstreamGemini.full("gemini",new JSONObject("{\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"合成G完整\"}]},\"finishReason\":\"STOP\"}]}"));check(nonstreamGemini.complete(),"Gemini non-stream parsed");
  AtomicInteger calls=new AtomicInteger();AtomicReference<String> mode=new AtomicReference<>("sse");AtomicReference<String> sent=new AtomicReference<>("");HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",exchange->{calls.incrementAndGet();sent.set(new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));String m=mode.get();if(m.equals("drop")){exchange.close();return;}if(m.equals("redirect")){exchange.getResponseHeaders().set("Location","/destination");exchange.sendResponseHeaders(307,-1);exchange.close();return;}if(m.equals("401")){byte[] b="{\"error\":{\"message\":\"SYNTHETIC_KEY invalid\"}}".getBytes();exchange.sendResponseHeaders(401,b.length);exchange.getResponseBody().write(b);exchange.close();return;}String data="data: {\"choices\":[{\"delta\":{\"content\":\"合成HTTP\"},\"finish_reason\":null}]}\n\ndata: {\"choices\":[{\"delta\":{},\"finish_reason\":\"stop\"}]}\n\ndata: [DONE]\n\n";if(m.equals("broken"))data="data: {\"choices\":[{\"delta\":{\"content\":\"部分\"}}]}\n\n";exchange.getResponseHeaders().set("Content-Type","text/event-stream");exchange.sendResponseHeaders(200,0);try(OutputStream out=exchange.getResponseBody()){for(byte b:data.getBytes(StandardCharsets.UTF_8)){out.write(b);out.flush();}}exchange.close();});server.start();
  try{String url="http://127.0.0.1:"+server.getAddress().getPort()+"/chat";JSONObject payload=ApiProtocol.payload(profile("chat"),"synthetic-model","",new JSONArray().put(J.obj("role","user","content","合成HTTP问题")));ApiProtocol.Output actual=new ApiClient().generateAt(profile("chat"),url,"SYNTHETIC_KEY",payload,o->{},true);check(actual.complete()&&actual.text.toString().equals("合成HTTP"),"real HTTP split UTF8 stream parsed");check(calls.get()==1&&new JSONObject(sent.get()).getJSONArray("messages").length()==1,"one send is exactly one HTTP request");
   for(String failure:new String[]{"drop","redirect","401","broken"}){mode.set(failure);int before=calls.get();String message="";try{new ApiClient().generateAt(profile("chat"),url,"SYNTHETIC_KEY",payload,o->{},true);}catch(Exception e){message=e.getMessage();}check(calls.get()==before+1,failure+" never automatically retries or follows redirect");check(!message.contains("SYNTHETIC_KEY"),failure+" hides API key from errors");}
  }finally{server.stop(0);}System.out.println("TOTAL "+tests+" PASSED");
 }
